  $target=tai_prov_target($q);$route=null;if($target!==null){if(empty($target['connected'])){$a=$target['label'].' n’est pas connecté au FIELD actuel. Les portances réellement connectées sont : '.implode(', ',tai_prov_labels($reg)).'. T^AI ne simulera pas '.$target['label'].' comme une voix réelle.';return array('status'=>200,'body'=>tai_prov_server($q,$context,$p,$a,$reg,'TARGET_NOT_CONNECTED',$target));}$port=tai_prov_find($reg,$target['id']);if($port){$p['portances']=array($port['ref']);$p['regime']='SINGLE';$route=array('id'=>$port['id'],'label'=>$port['label'],'provider'=>$port['provider'],'model'=>$port['model'],'source'=>'SERVER_ROUTER');}}
  $refs=isset($p['portances'])&&is_array($p['portances'])?$p['portances']:array('gemini_36');$regime=isset($p['regime'])?strtoupper($p['regime']):'SINGLE';$p['q']=tai_prov_contract($reg,$regime,$refs).$q;$r=tai_step_run_field($p,$lab,$rate);$b=isset($r['body'])&&is_array($r['body'])?$r['body']:array('status'=>'error','error'=>'INVALID_FIELD_BODY');
  $sel=array();foreach($refs as $x){$id=is_string($x)?$x:tai_ref_id($x);if($id!=='')$sel[$id]=1;}if(isset($b['voices'])&&is_array($b['voices']))foreach($b['voices'] as $i=>$v){$id=isset($v['id'])?$v['id']:'';$b['voices'][$i]['provenance_verified']=($id!==''&&isset($sel[$id]));}
  if($regime==='SINGLE'&&!tai_prov_simulation($q)){$a=isset($b['answer'])?(string)$b['answer']:'';if($a===''&&isset($b['voices']))foreach($b['voices'] as $v)if(isset($v['status'])&&$v['status']==='OK'&&!empty($v['answer'])){$a=$v['answer'];break;}if($a!==''&&tai_prov_false_voice($a)){$b['status']='partial';$b['provenance_violation']=true;$b['discarded_model_output']=true;$b['answer']='La portance appelée a produit des attributions qui ne correspondent pas au registre réel. T^AI a retenu cette sortie. Les voix réellement connectées sont : '.implode(', ',tai_prov_labels($reg)).'.';$b['provider']='T^';$b['model']='server-provenance-guard';$b['voices']=array();}}
  $b['registry_snapshot']=$reg;$b['provenance_contract']='SERVER_ENFORCED_V1';$b['provenance_verified']=true;if($route)$b['routed_portance']=$route;tai_prov_restore($b,$q);$b['winner']=null;$b['vote']=null;$b['global_score']=null;$b['automatic_optimization']=false;return array('status'=>isset($r['status'])?$r['status']:200,'body'=>$b);
}
